/* i18n.js — multi-idioma de Aleph (ES/EN). Patrón data-i18n + diccionarios EMBEBIDOS
 * (síncrono: el framework DC renderiza con el texto correcto, sin parpadeo de claves).
 *
 * Uso:
 *   - HTML estático:   <span data-i18n="auth.email">Email</span>
 *                      <input data-i18n-ph="auth.email_ph">      (placeholder)
 *                      <button data-i18n-title="comp.enviar">    (title)
 *   - JS del DC ({{ }}): t('clave')  (window.t global)
 *   - Cambiar idioma:  AlephI18n.setLang('en')  → guarda + recarga
 *
 * Idioma en localStorage 'aleph-lang' (espejo de 'aleph-theme'). Default ES.
 * Fallback: clave faltante en EN → ES; faltante en ES → la clave cruda.
 * Interpolación: t('k', {n: 3}) reemplaza {n}.
 */
