  /* ── CAPA DE MEMORIA DE TRADUCCIÓN (TM) ──────────────────────────────────
   * Para pantallas DC grandes (Cuarto, etc.) cablear cada string a {{ }} sería
   * cirugía sobre cientos de bindings. En su lugar: un mapa ES→EN keyed por el
   * texto fuente, aplicado por un MutationObserver DESPUÉS de cada re-render del
   * DC (también atrapa strings computados en JS que un {{ }} no vería). Es
   * ADITIVO: en pantallas ya cableadas (Home/Auth/Settings) su salida ya es EN,
   * que no es clave del mapa ES→EN → no-op. Solo actúa con lang()==='en'. */
