    /* [identidad visual §f] IDIOMA MEZCLADO — barrido de superficies con la UI en inglés.
     * Estos 39 nodos seguían en español porque son literales del HTML/JS que nunca pasan
     * por t(): la capa TM es su único traductor y no tenían entrada. Era exactamente lo
     * reportado ("popups en inglés con botones en español"): Conexiones, Catálogo,
     * Biblioteca, Inspección y los artículos de Ayuda contestaban en dos idiomas a la vez.
     * (El chip del modelo, la fuga más visible por estar en TODAS las pantallas, no se
     * arregla acá sino en el diccionario: sus 27 claves brain.* faltaban de los dos lados.) */
    // etiquetas del chip del modelo: viven en una tabla de datos de brain-status.js, no
    // pasan por t(). Sin estas, el chip quedaba mitad y mitad ("Incluido · unverified").
    "Incluido": "Included",
    "Incluido · estándar": "Included · standard",
    "Incluido · veloz": "Included · fast",
    "Sin modelo": "No model",
    "Modelo personalizado": "Custom model",
    /* [FIX-P8] EL CENTRO DE MODELOS · los literales de Modelos.dc.html. El módulo JS de
     * la pantalla ya es bilingüe por `L(es,en)`; lo que NO pasa por ahí es el HTML
     * estático, y su único traductor es esta capa. Sin estas entradas, la pantalla nueva
     * habría nacido con la misma fuga de idioma que el barrido acababa de cerrar.
     * Las claves van COLAPSADAS a un espacio: así es como translateStr() reintenta un
     * párrafo que el HTML partió en varias líneas. ("catálogo de conectores" ya está más
     * abajo — no se repite: una clave duplicada en un objeto JS pisa a la otra en silencio.) */
