    'Agente': 'Agent', 'Una tarea. Ves cada paso.': 'One task. You see every step.',
    'aquí toma forma lo que tu agente produce': 'this is where what your agent produces takes shape',
    'armando…': 'building…', 'la obra de esta sesión': "this session's work", 'listo para una tarea': 'ready for a task',
    '↓ descargar': '↓ download', '⟨⟩ fuente': '⟨⟩ source', '🖥 Mi pantalla': '🖥 My screen',
    'Asígnale una tarea — ej: «arma un informe del cierre de mayo» · @ para conectar tus archivos': 'Give it a task — e.g. «build a May close report» · @ to attach your files',

    // ── ONBOARDING ──
    'Educación': 'Education', 'Programación': 'Programming', '¿En qué trabajas?': 'What do you work on?',
    'Elige uno y te armo un Aleph para empezar. Un toque, sin formularios.': "Pick one and I'll build you an Aleph to get started. One tap, no forms.",
    'cierres, reportes, números': 'closes, reports, numbers', 'clases, ejercicios, guías': 'classes, exercises, guides',
    'lo armas tú a medida': 'you build it custom',

    // ── BIBLIOTECA ──
    'El pulso del taller': 'The pulse of the workshop', 'Escribe y prueba código': 'Writes and tests code',
    'Cierra los números de la semana': "Closes the week's numbers", 'Buscar Aleph…': 'Search Aleph…',
    'Todo lo que produjeron tus Aleph, día a día. Toca un día para ver qué salió.': 'Everything your Alephs produced, day by day. Tap a day to see what came out.',
    'Tus Aleph': 'Your Alephs', 'cada uno con su obra': 'each with its work', 'más': 'more', 'outputs · últimos': 'outputs · latest',

    // ── LANDING ──
    'Aleph construye agentes —Aleph— que hacen tu trabajo a la vista: leen tus datos, arman el entregable y te lo dejan listo. Tú miras, no adivinas.': "Aleph builds agents —Alephs— that do your work in the open: they read your data, build the deliverable and leave it ready. You watch, you don't guess.",
    'Construye tu primer Aleph': 'Build your first Aleph',
    'Arma uno dándole habilidades, o usa uno listo. Lo adaptas a lo que necesitas.': 'Build one by giving it skills, or use a ready-made one. Adapt it to exactly what you need.',
    'Bitácora': 'Log', 'CÓMO FUNCIONA': 'HOW IT WORKS', 'Asígnale una tarea. Mira cómo la hace.': 'Give it a task. Watch how it does it.',
    'El entregable queda listo: descárgalo, ábrelo en tu app o guárdalo. Y lo retomas cuando quieras.': 'The deliverable is ready: download it, open it in your app or save it. Pick it up again whenever you like.',
    'El mismo Aleph sirve a todo tu mundo. No es una herramienta —es la fábrica de tus agentes.': "The same Aleph serves your whole world. It's not a tool — it's the factory for your agents.",
    'Elige un Aleph': 'Pick an Aleph', 'Empieza gratis': 'Start free', 'Empieza gratis →': 'Start free →',
    'En dos minutos lo verás produciendo algo real. Sin tarjeta.': "In two minutes you'll see it producing something real. No card required.",
    'Ingresar': 'Log in',
    'La cognición es prestada y cambia cada mes. Lo que importa —y lo que es tuyo— es el entorno: tus datos, tus herramientas, tus reglas. Aleph te da el control de eso.': "Cognition is rented and changes every month. What matters — and what's yours — is the environment: your data, your tools, your rules. Aleph gives you control of that.",
    'La cognición es prestada y cambia; tu entorno —datos, herramientas, reglas— es tuyo. Incluso tu propia key, si quieres.': 'Cognition is rented and changes; your environment — data, tools, rules — is yours. Even your own key, if you want.',
    'Le das la tarea y lo miras hacerla —cada paso en la bitácora, el artefacto formándose.': 'You give it the task and watch it work — every step in the log, the artifact taking shape.',
    'Leyó 3 hojas de cálculo': 'Read 3 spreadsheets', 'Mira a un agente trabajar — ahí abajo, en vivo': 'Watch an agent work — right there, live',
    'No es un chatbot: es un agente equipado que hace el trabajo.': 'Not a chatbot — an equipped agent that does the work.',
    'No es un modelo pelado: es un agente con herramientas, memoria y acceso a tus datos. Viene listo para hacer, no para charlar.': "It's not a bare model: it's an agent with tools, memory and access to your data. It comes ready to act, not to chat.",
    'POR QUÉ FUNCIONA': 'WHY IT WORKS', 'Tienes el resultado': "You've got the result",
    'Todo pasa a la vista, y para enviar, gastar o borrar el Aleph te pide OK. Nada sale al mundo sin que lo apruebes.': 'Everything happens in the open, and to send, spend or delete the Aleph asks for your OK. Nothing goes out without your approval.',
    'Tu trabajo, bajo control': 'Your work, under control', 'Términos': 'Terms',
    'Tú eres dueño del entorno': 'You own the environment',
    'Tú eres dueño del entorno. El Aleph pone el trabajo.': 'You own the environment. The Aleph does the work.',
    'arma el cierre él mismo': 'builds the close itself', 'cierra los números de la semana': "closes the week's numbers",
    'clases, guías': 'classes, guides', 'copias, pegas, lo haces tú': 'you copy, paste, do it yourself',
    'sin tarjeta · tu primer Aleph en 2 min': 'no card required · your first Aleph in 2 min',
    'te dice cómo armar el cierre': 'tells you how to build the close', 'te lo deja listo para usar': 'leaves it ready to use',
    'una caja negra que charla': 'a black box that chats',

