    // ── CONECTAR ──
    'Conecta tus herramientas': 'Connect your tools', 'Autorizas tu cuenta': 'You authorize your account',
    'Copia la llave que aparece. Es la única vez que Zotero te la muestra — cópiala completa.': 'Copy the key that appears — this is the only time Zotero shows it, so copy it in full.',
    'Guarda': 'Save', 'Pégala aquí.': 'Paste it here.', 'Pegas el token': 'You paste your token',
    'Tu llave de Zotero': 'Your Zotero key', '↗ Crear tu llave en Zotero': '↗ Create your key in Zotero',
    '✓ Sin conexión — listo': '✓ No connection — ready',
    '🔒 Tu llave se guarda cifrada · la quitas cuando quieras.': '🔒 Your key is stored encrypted · remove it whenever you want.',
    '» (así puede GUARDAR citas, no solo leer) →': '» (so it can SAVE citations, not just read) →',
    'formato: P9NiFoyLeZu2bZ…vuQPDWsd (24 letras y números, sin prefijo)': 'format: P9NiFoyLeZu2bZ…vuQPDWsd (24 letters and numbers, no prefix)',
    'P9NiFoyLeZu2bZ…vuQPDWsd (24 letras y números, sin prefijo)': 'P9NiFoyLeZu2bZ…vuQPDWsd (24 letters and numbers, no prefix)',
    'Sin sesión iniciada: guardo tu conexión bajo una cuenta de prueba para esta demo (cifrada igual). En el producto, queda en tu cuenta.': 'Not signed in: I save your connection under a trial account for this demo (encrypted all the same). In the product, it stays in your account.',
    "Te llevo a crear una llave nueva en Zotero. Ahí: ponle un nombre (ej. 'Mi asistente') → marca «": "I'll take you to create a new key in Zotero. There: give it a name (e.g. 'My assistant') → check «",
    'Tu agente usa lo que tú le des acceso. Algunas cosas ya funcionan solas; otras te piden conectar tu cuenta — tú decides, se guarda cifrado y lo quitas cuando quieras.': "Your agent uses whatever you give it access to. Some things work on their own; others ask you to connect your account — you're in charge, it's stored encrypted and you remove it whenever you want.",
    'Listo — ya puedo buscar en la web con Exa (búsqueda neural).': 'Done — I can now search the web with Exa (neural search).',
    'Listo — ya puedo buscar papers, modelos y datasets en Hugging Face.': 'Ready — I can now search papers, models and datasets on Hugging Face.',
    'Listo — ya puedo consultar precios de mercado y series técnicas de Alpha Vantage.': 'Done — I can now look up market prices and technical series from Alpha Vantage.',
    'Listo — ya puedo obtener series macro de FRED (inflación, desempleo, tasas, PIB) con cambios mes a mes y año a año.': 'Done — I can now pull macro series from FRED (inflation, unemployment, rates, GDP) with month-over-month and year-over-year changes.',
    'Listo — ya puedo obtener series macro del Banco Mundial (PIB, inflación, deuda…) para cualquier país, sin que pongas ninguna llave.': 'Done — I can now pull macro series from the World Bank (GDP, inflation, debt…) for any country, with no key required.',
    'Listo — ya puedo leer las páginas que me compartas y crearte notas y tareas.': 'Done — I can now read the pages you share with me and create notes and tasks for you.',
    'Listo — ya puedo leer tu biblioteca de Zotero y guardar las citas que encuentre.': 'Done — I can now read your Zotero library and save the citations I find.',
    'Listo — ya puedo leer tus canales y preparar mensajes. Enviar te pide el OK.': 'Done — I can now read your channels and draft messages. Sending will ask for your approval.',
    'Listo — ya puedo leer tus cursos y armar tareas.': 'Done — I can now read your courses and build assignments.',
    'Listo — ya puedo leer tus documentos y modelos de Onshape.': 'Done — I can now read your Onshape documents and models.',
    'Listo — ya puedo leer tus repos y, en los que autorices con escritura, crearte commits.': 'Done — I can now read your repos and, in those you authorize for write access, create commits for you.',
    'Listo — ya puedo leer y crear archivos en tu Drive.': 'Done — I can now read and create files in your Drive.',
    'Listo — ya puedo preparar borradores de correo y leer tu bandeja. Enviar siempre te pide el OK.': 'Done — I can now draft emails and read your inbox. Sending will always ask for your approval.',
    'Listo — ya puedo traer documentación de librerías al día con Context7.': 'Done — I can now fetch up-to-date library documentation with Context7.',
    'Listo — ya puedo ver tu agenda y crear eventos. Los cambios importantes te piden el OK.': 'Done — I can now see your calendar and create events. Significant changes will ask for your approval.',
    'Listo — ya puedo ver tu producción registrada en ORCID y citarla.': 'Done — I can now see your registered output in ORCID and cite it.',
    'Listo — ya puedo ver tus contactos y negocios de HubSpot.': 'Done — I can now see your HubSpot contacts and deals.',
    'Listo — ya puedo ver tus cursos de Classroom y sus tareas.': 'Done — I can now see your Classroom courses and their assignments.',
    'Listo — ya puedo ver tus cursos de Moodle.': 'Done — I can now see your Moodle courses.',
    'Listo — ya puedo ver tus depósitos de Zenodo y citarlos.': 'Done — I can now see your Zenodo deposits and cite them.',
    'Listo — ya puedo ver tus issues y proyectos de Linear.': 'Done — I can now see your Linear issues and projects.',
    'Listo — ya puedo ver tus listas de materiales (BOM) de OpenBOM.': 'Done — I can now see your OpenBOM bills of materials (BOM).',
    'Listo — ya puedo ver tus proyectos de OSF.': 'Done — I can now see your OSF projects.',
